      .query(
        `INSERT INTO multiplayer_participants
           (id, room_id, role, identity_kind, identity_ref, display_name, persona_snapshot, status, joined_at, last_seen)
         VALUES (?, ?, 'host', 'user', ?, ?, '{}', 'active', ?, ?)`,
